def get_db_connection():
    return pg8000.dbapi.connect(
        host=os.environ.get("EXPERIMENT_DB_HOST", "sdl-experiment-db"),
        port=int(os.environ.get("EXPERIMENT_DB_INTERNAL_PORT", 5432)),
        database=os.environ.get("EXPERIMENT_DB_NAME", "sdl_experiments"),
        user=os.environ.get("EXPERIMENT_DB_USER", "sdl_admin"),
        password=os.environ.get("EXPERIMENT_DB_PASSWORD", "sdl_secure_2025"),
    )


# ============================================================================
# HELPER FUNCTIONS
# ============================================================================


def parse_numeric(value: str):
    """Extract a numeric value from a string like '25 °C' or '100 mM'.

    Call this ONLY for a single-valued field eLabFTW types as a number. On a text field
    it is destructive - '20 mM NaAc' becomes 20.0 and the buffer identity is gone - and
    on a delimited list it keeps only the first element. When in doubt, store the
    original string unchanged.
    """

    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)

    text = str(value).strip()
    if text == "":
        return None

    import re

    # Replace comma decimal with dot if it looks like a single number
    if re.fullmatch(r"[-+]?\d+,\d+", text):
        text = text.replace(",", ".")

    match = re.search(r"[-+]?\d*\.?\d+", text)
    if match:
        try:
            return float(match.group())
        except ValueError:
            return None
    return None


def parse_field(value, field_type: str = None):
    """Route an eLabFTW value by what it IS, not by which parameter it came from.

    Any field may arrive as a delimited list, so the delimiter check comes first.
    """

    if value is None or value == "":
        return None
    if isinstance(value, (list, int, float)):
        return value

    text = str(value).strip()

    # a list if a delimiter separates more than one token; "1,5" (decimal comma) is one
    for sep in (";", ","):
        parts = [p.strip() for p in text.split(sep) if p.strip()]
        if len(parts) > 1:
            # Check if this is actually a single number with decimal comma
            if sep == "," and len(parts) == 2:
                import re

                if re.fullmatch(r"[-+]?\d+", parts[0]) and re.fullmatch(
                    r"\d+", parts[1]
                ):
                    # Looks like decimal comma (e.g. "1,5"), not a list
                    break
            # Try numeric list
            try:
                return [float(p) for p in parts]
            except ValueError:
                return parts

    if field_type == "number":
        numeric = parse_numeric(text)
        return numeric if numeric is not None else text

    return text


def find_experiment_json(elab_id: int) -> Path:
    """Find experiment JSON file."""

    paths = [
        Path(f"../experiment_{elab_id}.json"),
        Path(f"../data/experiment_{elab_id}.json"),
    ]
    for p in paths:
        if p.exists():
            return p
    raise FileNotFoundError(f"Experiment JSON not found for {elab_id}")


def load_workflow():
    """Load workflow.json and extract lab_id."""

    workflow_path = Path("../workflow.json")
    if workflow_path.exists():
        with open(workflow_path) as f:
            data = json.load(f)
            return data, data.get("lab_id") or data.get("labId")
    return None, None


def extract_metadata(extra_fields: dict) -> dict:
    """Extract and map metadata from eLabFTW extra fields."""

    metadata: dict = {}
    for elab_name, db_name in FIELD_MAPPING.items():
        if elab_name not in extra_fields:
            continue
        field = extra_fields[elab_name]
        value = field.get("value")
        field_type = field.get("type")  # e.g. 'number' or 'text'
        parsed = parse_field(value, field_type=field_type)
        metadata[db_name] = parsed
    return metadata


def list_folder_files(folder_path: Path) -> list:
    """List files in a folder."""

    folder = Path(folder_path)
    if folder.exists() and folder.is_dir():
        return [f.name for f in folder.iterdir() if f.is_file()]
    return []


def build_raw_data(elab_id: int) -> dict:
    """Build raw_data JSONB structure."""

    data_folder = Path("../data")
    return {
        "folder_path": str(data_folder.resolve()),
        "files": list_folder_files(data_folder),
    }


def load_analysis_results(elab_id: int) -> dict:
    """Load analysis_results_<ID>.json if present, and basic derivatives."""

    results_folder = Path("../results")
    analysis_json_path = results_folder / f"analysis_results_{elab_id}.json"
    analysis_data = None
    if analysis_json_path.exists():
        try:
            with open(analysis_json_path, "r") as f:
                analysis_data = json.load(f)
        except Exception:
            analysis_data = None

    return analysis_data or {}


def build_results(elab_id: int) -> dict:
    """Build results JSONB structure from analysis outputs and folder listing."""

    results_folder = Path("../results")
    analysis_data = load_analysis_results(elab_id)

    # Determine analysis status and message from analysis_results JSON
    status_raw = analysis_data.get("status")
    if status_raw == "success":
        analysis_status = "completed"
    elif status_raw in {"failed", "error"}:
        analysis_status = "failed"
    else:
        analysis_status = "pending"

    message = analysis_data.get("message", "")

    # Peaks list (already in suitable structure in analysis_results)
    peaks = analysis_data.get("peaks", [])

    # Simple summary metrics
    n_peaks = len(peaks) if isinstance(peaks, list) else 0
    first_peak_rt = None
    last_peak_rt = None
    if n_peaks > 0:
        try:
            rts = [p.get("retention_time_min") for p in peaks if "retention_time_min" in p]
            rts = [float(rt) for rt in rts if rt is not None]
            if rts:
                first_peak_rt = min(rts)
                last_peak_rt = max(rts)
        except Exception:
            first_peak_rt = None
            last_peak_rt = None

    # Data files and plots from analysis_results structure
    data_files = {}
    plots = {}

    data_outputs = analysis_data.get("data_outputs") or {}
    if isinstance(data_outputs, dict):
        if "chromatogram_csv" in data_outputs:
            data_files["chromatogram_csv"] = data_outputs["chromatogram_csv"]

    plots_dict = analysis_data.get("plots") or {}
    if isinstance(plots_dict, dict):
        chrom = plots_dict.get("chromatogram") or {}
        if isinstance(chrom, dict):
            png = chrom.get("png")
            pdf = chrom.get("pdf")
            if png:
                plots["chromatogram_png"] = png
            if pdf:
                plots["chromatogram_pdf"] = pdf

    # Paths based on expected naming even if analysis_results is missing
    if "chromatogram_csv" not in data_files:
        csv_path = results_folder / f"akta_chromatogram_processed_{elab_id}.csv"
        if csv_path.exists():
            data_files["chromatogram_csv"] = str(csv_path.resolve())

    if "chromatogram_png" not in plots:
        png_path = results_folder / f"chromatogram_{elab_id}.png"
        if png_path.exists():
            plots["chromatogram_png"] = str(png_path.resolve())

    if "chromatogram_pdf" not in plots:
        pdf_path = results_folder / f"chromatogram_{elab_id}.pdf"
        if pdf_path.exists():
            plots["chromatogram_pdf"] = str(pdf_path.resolve())

    # Always include analysis_results JSON path if present
    analysis_results_json_path = results_folder / f"analysis_results_{elab_id}.json"
    if analysis_results_json_path.exists():
        data_files["analysis_results_json"] = str(analysis_results_json_path.resolve())

    results_obj = {
        "analysis_status": analysis_status,
        "analysis_timestamp": datetime.now(timezone.utc).isoformat(),
        "analysis_message": message,
        "summary": {
            "n_peaks": n_peaks,
            "first_peak_rt_min": first_peak_rt,
            "last_peak_rt_min": last_peak_rt,
        },
        "peaks": peaks,
        "data_files": data_files,
        "plots": plots,
        "raw_analysis": analysis_data,
    }

    return results_obj


# ============================================================================
# MAIN FUNCTIONS
# ============================================================================


def upsert_process_schema(cursor):
    """Insert or update process schema."""

    cursor.execute(
        """
        INSERT INTO process_schemas (
            process_id, process_name, version,
            metadata_schema, results_schema, field_mapping, expected_files
        ) VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (process_id) DO UPDATE SET
            process_name = EXCLUDED.process_name,
            metadata_schema = EXCLUDED.metadata_schema,
            results_schema = EXCLUDED.results_schema,
            field_mapping = EXCLUDED.field_mapping,
            expected_files = EXCLUDED.expected_files,
            updated_at = NOW()
    """,
        (
            PROCESS_ID,
            PROCESS_NAME,
            PROCESS_VERSION,
            json.dumps(METADATA_SCHEMA),
            json.dumps(RESULTS_SCHEMA),
            json.dumps(FIELD_MAPPING),
            json.dumps(EXPECTED_FILES),
        ),
    )


def upsert_experiment(cursor, elab_id: int, data: dict) -> int:
    """Insert or update experiment execution."""

    cursor.execute(
        """
        INSERT INTO experiment_executions (
            elab_id, elab_title, process_id, process_name, lab_id,
            status, "user", workflow_json, metadata, raw_data, results
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (elab_id) DO UPDATE SET
            elab_title = EXCLUDED.elab_title,
            status = EXCLUDED.status,
            metadata = EXCLUDED.metadata,
            raw_data = EXCLUDED.raw_data,
            results = EXCLUDED.results,
            workflow_json = EXCLUDED.workflow_json,
            updated_at = NOW()
        RETURNING id
    """,
        (
            elab_id,
            data["title"],
            PROCESS_ID,
            PROCESS_NAME,
            data["lab_id"],
            data["status"],
            data["user"],
            json.dumps(data["workflow_json"]) if data["workflow_json"] is not None else None,
            json.dumps(data["metadata"]),
            json.dumps(data["raw_data"]),
            json.dumps(data["results"]),
        ),
    )
    row = cursor.fetchone()
    return int(row[0])


def main() -> int:
    parser = argparse.ArgumentParser(
        description=f"Commit {PROCESS_NAME} to database"
    )
    parser.add_argument("elab_id", type=int, help="eLabFTW experiment ID")
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Don't commit, just show what would be done",
    )
    parser.add_argument(
        "--init-schema-only",
        action="store_true",
        help="Only initialize process schema",
    )
    args = parser.parse_args()

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Always upsert schema
        upsert_process_schema(cursor)
        print(f"Process schema updated: {PROCESS_NAME} (ID: {PROCESS_ID})")

        if args.init_schema_only:
            conn.commit()
            print("Schema-only mode, skipping experiment data.")
            return 0

        # Load experiment data
        exp_json_path = find_experiment_json(args.elab_id)
        with open(exp_json_path, "r") as f:
            exp_data = json.load(f)

        # Extract fields
        extra_fields = (
            exp_data.get("metadata_decoded", {}).get("extra_fields", {}) or {}
        )
        workflow_json, lab_id = load_workflow()

        # Build data structures
        metadata = extract_metadata(extra_fields)
        raw_data = build_raw_data(args.elab_id)
        results = build_results(args.elab_id)

        data = {
            "title": exp_data.get("title", ""),
            "lab_id": lab_id,
            "status": results.get("analysis_status", "pending"),
            "user": exp_data.get("userid_human", ""),
            "workflow_json": workflow_json,
            "metadata": metadata,
            "raw_data": raw_data,
            "results": results,
        }

        if args.dry_run:
            print("DRY RUN - Would insert the following payload:")
            print(json.dumps(data, indent=2, default=str))
            conn.rollback()
            return 0

        # Commit to database
        exp_db_id = upsert_experiment(cursor, args.elab_id, data)
        conn.commit()

        print(
            f"Experiment {args.elab_id} committed successfully (DB ID: {exp_db_id})"
        )
        return 0

    except Exception as e:
        print(f"Error during commit: {e}", file=sys.stderr)
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        return 1
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


if __name__ == "__main__":  # pragma: no cover
    sys.exit(main())

